import java.io.*;import com.jpexs.decompiler.flash.*;import com.jpexs.decompiler.flash.tags.*;import com.jpexs.decompiler.flash.abc.*;
class ProbeRename {public static void main(String[] a)throws Exception{SWF s=new SWF(new FileInputStream(a[0]),true);for(Tag t:s.getTags()){if(t instanceof ABCContainerTag){ABC abc=((ABCContainerTag)t).getABC();for(int i=1;i<abc.constants.getStringCount();i++)if(abc.constants.getString(i).equals("Engine"))abc.constants.setString(i,"MountRuntimeProbe");t.setModified(true);}if(t instanceof SymbolClassTag){SymbolClassTag x=(SymbolClassTag)t;for(int i=0;i<x.names.size();i++)if(x.names.get(i).equals("Engine"))x.names.set(i,"MountRuntimeProbe");t.setModified(true);}}try(OutputStream o=new FileOutputStream(a[1])){s.saveTo(o);}}}
